describe('Home Page Navigation', () => {
    beforeEach(() => {
        cy.visit('http://example.com'); // Replace with the actual URL of the application
    });

    it('should navigate to the home page when the logo is clicked', () => {
        cy.get('.logo').click(); // Replace with the actual selector for the logo
        cy.url().should('eq', 'http://example.com/home'); // Replace with the actual home page URL
        cy.get('h1').should('contain', 'Welcome to the Home Page'); // Replace with actual content on the home page
    });

    it('should not navigate to the home page if the logo is not clickable', () => {
        cy.get('.non-clickable-logo').should('not.exist'); // Replace with a selector that should not exist
        cy.get('.logo').click(); // Attempt to click the logo
        cy.url().should('not.eq', 'http://example.com/home'); // Ensure it does not navigate
    });
});
